  { name: 'PROD_MIXPANEL_KEY', service: 'Mixpanel', type: 'api_key', rotation_days: 90, last_rotated: null, owner: 'analytics_team', category: 'analytics' },
  { name: 'PROD_HOTJAR_KEY', service: 'Hotjar', type: 'api_key', rotation_days: 90, last_rotated: null, owner: 'analytics_team', category: 'analytics' },
  { name: 'PROD_GMAIL_OAUTH2', service: 'Gmail', type: 'oauth2', rotation_days: 90, last_rotated: null, owner: 'platform_team', category: 'google_suite' },
  { name: 'PROD_GCAL_OAUTH2', service: 'Google Calendar', type: 'oauth2', rotation_days: 90, last_rotated: null, owner: 'platform_team', category: 'google_suite' },
  { name: 'PROD_GDRIVE_OAUTH2', service: 'Google Drive', type: 'oauth2', rotation_days: 90, last_rotated: null, owner: 'platform_team', category: 'google_suite' },
  { name: 'PROD_GSHEETS_OAUTH2', service: 'Google Sheets', type: 'oauth2', rotation_days: 90, last_rotated: null, owner: 'platform_team', category: 'google_suite' },
  { name: 'PROD_SLACK_OAUTH2', service: 'Slack', type: 'oauth2', rotation_days: 90, last_rotated: null, owner: 'platform_team', category: 'communication' },
  { name: 'PROD_MSTEAMS_OAUTH2', service: 'Microsoft Teams', type: 'oauth2', rotation_days: 90, last_rotated: null, owner: 'platform_team', category: 'communication' },
