  { name: 'PROD_SUPABASE_KEY', service: 'Supabase', type: 'api_key', rotation_days: 90, last_rotated: null, owner: 'engineering_team', category: 'data_storage' },
  { name: 'PROD_N8N_GATEWAY_API_KEY', service: 'n8n API Gateway', type: 'api_key', rotation_days: 180, last_rotated: null, owner: 'platform_team', category: 'internal' }
];

const now = new Date();
const alerts = credentials.map(cred => {
  let daysSinceRotation = null;
  let daysUntilExpiry = null;
  let status = 'UNKNOWN';

  if (cred.last_rotated) {
    const lastRotated = new Date(cred.last_rotated);
    daysSinceRotation = Math.floor((now - lastRotated) / (1000 * 60 * 60 * 24));
    daysUntilExpiry = cred.rotation_days - daysSinceRotation;
    status = daysUntilExpiry <= 0 ? 'EXPIRED' : daysUntilExpiry <= 14 ? 'EXPIRING_SOON' : 'OK';
  } else {
    // No rotation date recorded — flag for initial setup
    status = 'NEEDS_INITIAL_ROTATION';
  }

  return {
    ...cred,
    days_since_rotation: daysSinceRotation,
    days_until_expiry: daysUntilExpiry,
    status: status,
    needs_alert: status !== 'OK'
  };
});

// Group by status for the report
const expired = alerts.filter(c => c.status === 'EXPIRED');
const expiringSoon = alerts.filter(c => c.status === 'EXPIRING_SOON');
const needsSetup = alerts.filter(c => c.status === 'NEEDS_INITIAL_ROTATION');
const ok = alerts.filter(c => c.status === 'OK');

return [{
  json: {
    credentials: alerts,
    summary: {
      total: alerts.length,
      ok: ok.length,
      expired: expired.length,
      expiring_soon: expiringSoon.length,
      needs_setup: needsSetup.length
    },
    checked_at: now.toISOString(),
    has_issues: expired.length > 0 || expiringSoon.length > 0
  }
}];

const data = $input.first().json;
const alertCredentials = data.credentials.filter(c => c.status === 'EXPIRED' || c.status === 'EXPIRING_SOON');

const credentialBlocks = alertCredentials.map(cred => {
  const statusIcon = cred.status === 'EXPIRED' ? ':red_circle:' : ':warning:';
  return {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `${statusIcon} *${cred.service}* (${cred.name})\nStatus: ${cred.status}` },
      { type: 'mrkdwn', text: `Type: ${cred.type} | Category: ${cred.category}\nOwner: ${cred.owner}` },
      { type: 'mrkdwn', text: `Last Rotated: ${cred.last_rotated || 'Never'}\nDays Since: ${cred.days_since_rotation || 'N/A'}` },
      { type: 'mrkdwn', text: `Rotation Policy: ${cred.rotation_days} days\nDays Until Expiry: ${cred.days_until_expiry || 'N/A'}` }
    ]
  };
});

const slackPayload = {
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: 'Credential Rotation Alert', emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: `*${data.summary.expired} expired* | *${data.summary.expiring_soon} expiring soon* | *${data.summary.ok} OK* | Total: ${data.summary.total}` } },
    { type: 'divider' },
    ...credentialBlocks,
    { type: 'divider' },
    { type: 'section', text: { type: 'mrkdwn', text: '*Action Required:* Rotate expired credentials in the n8n credentials UI. For OAuth2, re-authenticate. For API keys, regenerate from provider dashboard.' } }
  ]
};

return [{ json: slackPayload }];
